head.script:
// 결함 재현 시나리오 설명
scwin.tData = {
    "description" : "[FAIL] multiselect accessibility=true + singleSelect=true 일 때 ArrowDown 으로 포커스 이동 후 Enter 키 입력 시 아이템 선택이 동작하지 않는 결함 재현",
    "validation" : [
        "API 가이드 spec : accessibility=true 이고 singleSelect=true 이면 Enter 키로도 아이템을 선택할 수 있어야 합니다.",
        "현재 실제 동작 : Enter 키 입력 시 아이템 선택이 발생하지 않음 (Space 키로는 정상 선택됨).",
        "원인 : 엔진 multiselect.js handleKeydownEvent (line 2620) 에서 Enter 키 분기 조건이 'singleSelect===true && enterKeySelect===true' 인데, defaultOptions(line 1061~1090)에 enterKeySelect 가 정의되지 않아 항상 undefined → false 로 평가되어 dead code 가 됨."
    ]
}



scwin.onpageload = function () {
    var sysInfo = "─── 결함 재현 환경 ───";
    scwin.setReturnValue(sysInfo);
    scwin.setReturnValue("컴포넌트 : multiselect");
    scwin.setReturnValue("속성 조건 : accessibility=true, singleSelect=true");
    scwin.setReturnValue("");
    scwin.setReturnValue("─── 재현 절차 ───");
    scwin.setReturnValue("1. multiselect 컴포넌트 영역에 마우스 클릭하여 포커스");
    scwin.setReturnValue("2. ArrowDown 키 입력 → 첫 번째 아이템에 focus 이동 (aria-activedescendant 설정 확인)");
    scwin.setReturnValue("3-A. Space 키 입력 → 현재 focus 된 아이템 선택 (정상 동작)");
    scwin.setReturnValue("3-B. Enter 키 입력 → 현재 focus 된 아이템 선택 (결함 : 미동작)");
    scwin.setReturnValue("4. '결과 확인' 버튼 클릭 → getValue/getSelectedIndex 출력");
    scwin.setReturnValue("");
    scwin.setReturnValue("─── 기대 vs 실제 ───");
    scwin.setReturnValue("기대 : Space, Enter 모두 동일하게 아이템 선택");
    scwin.setReturnValue("실제 : Space 만 정상, Enter 는 미동작");
    scwin.setReturnValue("");
};



// 결과 확인 (getValue / getSelectedIndex 출력)
scwin.btn_getResult_onclick = function (e) {
    scwin.setReturnValue("─── 결과 확인 (target1: accessibility=true, singleSelect=true) ───");
    scwin.setReturnValue("getValue : " + target1.getValue());
    scwin.setReturnValue("getSelectedIndex : " + target1.getSelectedIndex());
    scwin.setReturnValue("aria-activedescendant : " + (document.getElementById("target1_ul") ? document.getElementById("target1_ul").getAttribute("aria-activedescendant") : "N/A"));
    scwin.setReturnValue("");
};



// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정 (독립 실행용 — body_bottom.xml 미사용)
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
